/** Complete explicit compact construction capability and ordinary runtime adapter. */
class LocalSunCompactConstructionProfile {
	/** Complete accepted physical owners. */ readonly models: LocalSunCompactProfileModels;
	/** Shared Native15 basis and source packet. */ readonly spectral: Algorithm32ExecutionSpectralProfile;
	/** Actual compact domains and packing. */ readonly domains: LocalSunCompactConstructionDomains;
	/** Qualified local numerical policies. */ readonly numerical: LocalSunCompactNumericalPolicies;
	/** Named complete physical/numerical identity. */ readonly id: string;
	/** Current canonical executable-fact hash. */ readonly contentHash: string;
	/** Input derivation identity. */ readonly provenanceIdentity: string;
	/** Revision of the explicit profile contract. */ readonly revision: number;
	/** Creates the complete compact profile from accepted existing models and authored topology seeds. */
	constructor(definition: LocalSunCompactConstructionProfileDefinition);
	/** Call this method to reject fabricated profiles and changed retained physical facts. */
	static assert(profile: unknown): LocalSunCompactConstructionProfile;
	/** Call this method to select analytic compact construction and lookup through the ordinary facade. */
	createExecutionProfile(): Algorithm32ExecutionProfile;
	/** Call this method to estimate all declared logical owned GPU payload before admission. */
	estimateResources(request: LocalSunCompactResourceEstimateRequest): LocalSunCompactResourceEstimate;
}
